import{_ as t,o as d,c,a3 as o}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"命令行概览","description":"clice 是单一可执行文件。编辑器启动 clice serve 并通过 LSP 与之通信；其余子命令在终端中驱动同一个引擎，共用其编译数据库处理、缓存和索引。","frontmatter":{"head":[["meta",{"property":"og:title","content":"命令行概览 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/overview"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/overview"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/overview"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/overview"}],["meta",{"property":"og:description","content":"clice 是单一可执行文件。编辑器启动 clice serve 并通过 LSP 与之通信；其余子命令在终端中驱动同一个引擎，共用其编译数据库处理、缓存和索引。"}]]},"headers":[],"relativePath":"zh/clice/cli/overview.md","filePath":"zh/clice/cli/overview.md","lastUpdated":1794738697000}'),a={name:"zh/clice/cli/overview.md"};function r(i,e,l,n,s,h){return d(),c("div",null,[...e[0]||(e[0]=[o('<h1 id="command-line-overview" tabindex="-1"><span id="命令行概览" class="heading-alias"></span>命令行概览 <a class="header-anchor" href="#command-line-overview" aria-label="Permalink to &quot;命令行概览&quot;">​</a></h1><p>clice 是单一可执行文件。编辑器启动 <code>clice serve</code> 并通过 LSP 与之通信；其余子命令在终端中驱动同一个引擎，共用其编译数据库处理、缓存和索引。</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>页面</th></tr></thead><tbody><tr><td><code>serve</code></td><td>启动语言服务器。编辑器会代为启动，参见编辑器设置。</td><td><a href="./../guide/editors">editors</a></td></tr><tr><td><code>lint</code></td><td>借助 worker 池对每个翻译单元运行 clang-tidy。</td><td><a href="./lint">lint</a></td></tr><tr><td><code>index</code></td><td>提前为项目建立索引，让服务器热启动。</td><td><a href="./">index</a></td></tr><tr><td><code>format</code></td><td>用 clang-format 格式化项目中的文件。</td><td><a href="./format">format</a></td></tr><tr><td><code>inspect</code></td><td>对单个源文件运行某项功能，将原始结果输出为 JSON。</td><td></td></tr><tr><td><code>command</code></td><td>显示文件编译时所用的命令，并为其他工具转换编译命令。</td><td><a href="./command">command</a></td></tr><tr><td><code>query</code></td><td>向持久化索引查询符号、引用、调用图和文件。</td><td><a href="./query">query</a></td></tr><tr><td><code>refactor</code></td><td>依据持久化索引在整个项目中重命名符号。</td><td><a href="./refactor">refactor</a></td></tr><tr><td><code>analyze</code></td><td>报告重构所需的事实信息，例如模块依赖和循环依赖。</td><td><a href="./analyze">analyze</a></td></tr><tr><td><code>modularize</code></td><td>将第三方库封装为 C++20 模块，将程序改写为模块单元。</td><td><a href="./modularize">modularize</a></td></tr><tr><td><code>scan</code></td><td>扫描构建的包含依赖与模块依赖，并为扫描计时。</td><td><a href="./scan">scan</a></td></tr></tbody></table><p><code>inspect</code> 没有单独页面：<code>clice inspect --help</code> 列出了它的各项操作和选项。</p><h2 id="arguments" tabindex="-1"><span id="参数" class="heading-alias"></span>参数 <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>每个子命令都以相同方式接受参数：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clice &lt;command&gt; [&lt;operation&gt;] [&lt;target&gt;...] [--option...]</span></span></code></pre></div><ul><li>承担多项工作的命令，用紧随其后的一个词指明具体操作：<code>clice query references</code>、<code>clice index stats</code>、<code>clice analyze modules edge</code>。有默认主任务的命令，后面不跟操作词时直接执行该任务：<code>clice index</code> 建立索引，<code>clice analyze modules</code> 输出概览，<code>clice command &lt;file&gt;</code> 显示该文件的编译命令。在任意命令或操作之后加上 <code>--help</code>，即可列出它接受的参数。</li><li>目标（即操作针对的符号或文件）跟在操作之后：<code>clice query references &quot;shapes::Circle::area&quot;</code>、<code>clice query document-symbols src/main.cpp</code>。凡是接受符号的位置，均以<a href="./query#locators">定位符</a>（locator）指明符号；文件则以路径指明，相对于当前目录的相对路径或绝对路径均可；命令行上的其他路径（如分区文件或输出目录）也是如此。</li><li>选项放在操作之后。需要传入多个值时，重复给出该选项即可：<code>--scope &#39;src/**&#39; --scope &#39;include/**&#39;</code>。</li><li><code>--workspace &lt;dir&gt;</code> 指定项目根目录；未指定时，命令作用于当前目录所属的项目，查找方式与 git 查找仓库相同：从当前目录向上找最近的含有 <code>clice.toml</code>、<code>.clice/config.toml</code> 或 <code>compile_commands.json</code> 的目录（直接位于该目录下，或位于其 <code>build/</code> 子目录中），若均未找到则取当前目录本身（<code>inspect</code> 与编辑器一样，从目标文件所在位置向上查找）。若配置无法使用——配置文件无法解析、值类型有误，或存在命令无法遵照执行的选项——命令会以退出码 2 失败，并逐一标出问题及其在文件中的位置；<code>--configuration &lt;tag&gt;</code> 固定构建配置，优先级高于编辑器持久化的选择（参见<a href="./../guide/config-guide#several-builds">构建配置</a>）；<code>-j</code>、<code>--jobs &lt;n&gt;</code> 指定 <code>index</code>、<code>lint</code> 和 <code>format</code> 同时处理的翻译单元或文件数量；环境变量 <code>CLICE_LOG_LEVEL</code> 控制输出到 stderr 的日志级别，默认为警告和错误（<code>serve</code> 的 stderr 会展示在编辑器中，因此默认从 <code>info</code> 起输出）；无论该环境变量设为多少，<code>serve</code>、<code>index</code> 和 <code>lint</code> 的会话日志始终保留 <code>info</code> 级别。</li></ul><h2 id="exit-codes" tabindex="-1"><span id="退出码" class="heading-alias"></span>退出码 <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;退出码&quot;">​</a></h2><p>每个命令都以下列四种退出码之一结束，具体细节见各命令页面：</p><table tabindex="0"><thead><tr><th>退出码</th><th>含义</th></tr></thead><tbody><tr><td><code>0</code></td><td>命令完成了所请求的操作。</td></tr><tr><td><code>1</code></td><td>操作已完成，但结果为否定：存在 Lint 问题、有文件需要格式化、未找到符号或文件、重命名存在冲突，或有翻译单元索引失败。</td></tr><tr><td><code>2</code></td><td>无法完成操作：参数或配置无法解析、没有可处理的对象（没有项目、没有编译数据库、没有翻译单元），或无法打开索引。</td></tr><tr><td><code>130</code></td><td>运行被中断。</td></tr></tbody></table>',11)])])}const f=t(a,[["render",r]]);export{m as __pageData,f as default};
